//! 🧫️ Real admitted payload fixtures retain one original caller stock and all physical receipts.
use semio_framework_job::*;
#[cfg(test)] use semio_framework_job_payload::payload_builder::RetainedPayloadBuilder;
#[cfg(test)] use semio_framework_job_payload::payload_pages_and_ledger::JobPayloadStream;
fn clock()->Option<u64>{Some(1000)}
const STOCK:RetainedCloneGrant=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:64};
pub const PAYER:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:64};
/// 🏦️ Births one caller that only pays the effects of closing standalone owners.
pub fn payer(operation:OperationId,generation:Generation)->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(operation,generation,PAYER,clock,1000000,1<<30)}
pub const BIRTH:RetainedCloneGrant=STOCK;
pub const SOURCE:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16384,maximum_release_bytes:1048576,maximum_depth:64};
pub fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
/// 🧾️ Settles one builder step on a standalone borrowed context by posting its actual receipt and work once.
pub fn settle(cx:&mut StepContext<'_>,turn:semio_framework_value::RetainedWorkOutcome)->RetainedCloneStep{let step=turn.result.unwrap();cx.consume_retained(step.progress()).unwrap();cx.consume_work(turn.work);step}
/// 🪙️ Runs one close inside a real effect of the caller; an unaffordable grant hands back an unmoved zero-work step.
pub fn closed<E:std::fmt::Debug>(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,close:impl FnOnce(&mut semio_framework_value::RetainedAllocationEffect<'_>)->semio_framework_value::RetainedWorkOutcome<RetainedCloneStep,E>)->(RetainedCloneStep,u128){match caller.with_effect(grant,close){Ok(turn)=>(turn.result.unwrap(),turn.work),Err(_)=>(RetainedCloneStep::Progress(Default::default()),0)}}
/// 🪙️ Closes one builder step inside the effect of the borrowed original turn.
pub fn close_builder(builder:&mut RetainedPayloadBuilder,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{let demand=builder.retirement_demands()?;close_original_effect_step(cx,demand,|effect|semio_framework_value::RetainedWorkPoll::Complete(builder.close_step(effect)))}
pub struct OriginalTestPayload{pub caller:OriginalJobFixtureCaller,pub builder:RetainedPayloadBuilder,pub decoder:OriginalJobDecodeOwner,born:usize,released:usize}
impl OriginalTestPayload{
 /// 🎟️ Observes an original owner that already posts its own work and physical receipt.
 pub fn original_turn<R>(&mut self,grant:RetainedCloneGrant,run:impl FnOnce(&mut RetainedPayloadBuilder,&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{let(result,heap)=observe(||self.caller.turn_with_decoder(OriginalJobFixtureCaller::refreshed(grant),&mut self.decoder,|cx|{let mut value=None;cx.with_retained_loan(grant,|cx|{value=Some(run(&mut self.builder,cx)?);Ok(())})?;Ok(value.expect("original payload callback returned its value"))}));self.record(heap);result}
 /// 🧾️ Observes a native construction turn whose physical receipt posts at its own settlement turn, so only the cumulative heap and receipts balance.
 pub fn original_construction_turn<R>(&mut self,grant:RetainedCloneGrant,run:impl FnOnce(&mut RetainedPayloadBuilder,&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->(Result<R,OriginalTurnFailure>,(usize,usize),RetainedCloneProgress){let(result,heap)=observe(||self.caller.turn_with_decoder(OriginalJobFixtureCaller::refreshed(grant),&mut self.decoder,|cx|{let mut value=None;cx.with_retained_loan(grant,|cx|{value=Some(run(&mut self.builder,cx)?);Ok(())})?;Ok(value.expect("original payload callback returned its value"))}));self.born+=heap.0;self.released+=heap.1;(result,heap,self.caller.receipt())}
 pub fn admit(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize)->Self{Self::prepare(operation,generation,stream,source,extent,false)}
 pub fn admit_single_page(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize)->Self{assert!(source.len()<=extent);Self::prepare(operation,generation,stream,source,extent,source.is_empty())}
 fn prepare(operation:OperationId,generation:Generation,stream:JobPayloadStream,source:&[u8],extent:usize,reserve_empty:bool)->Self{assert!(extent>0&&extent<=JOB_PAYLOAD_PAGE_BYTES);let caller=OriginalJobFixtureCaller::admit(operation,generation,STOCK,clock,1000000,100000);let heap=(caller.born_bytes(),0);let mut original=Self{caller,builder:RetainedPayloadBuilder::new(stream),decoder:OriginalJobDecodeOwner::empty(),born:heap.0,released:heap.1};let grant=RetainedCloneGrant{maximum_capacity_bytes:extent,..SOURCE};let mut cursor=0;let empty_source=[0u8];let mut empty_cursor=0;for turn in 0..4096{if original.builder.published().is_some(){break}let(answer,heap)=observe(||original.caller.turn(grant,|cx|{let turn=if !original.builder.is_initialized(){original.builder.advance_initialization(cx)}else if reserve_empty&&original.builder.original().unwrap().page_count()==0{let turn=original.builder.append_original(cx,&empty_source,&mut empty_cursor);assert_eq!(empty_cursor,0);turn}else if cursor<source.len(){original.builder.append_original(cx,source,&mut cursor)}else{original.builder.seal(cx)};receive_original_retained_work(cx,turn)?;Ok(())}));answer.unwrap();original.record(heap);assert!(turn<4095);}assert!(original.builder.published().is_some());assert_eq!(cursor,source.len());original}
 fn record(&mut self,heap:(usize,usize)){let receipt=self.caller.receipt();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));self.born+=heap.0;self.released+=heap.1;}
 /// 🏦️ The source grant widened to what the caller's own closure demands of one turn.
 pub fn retire_grant(&self)->RetainedCloneGrant{let demand=self.caller.retirement_demands().unwrap();RetainedCloneGrant{maximum_copy_bytes:SOURCE.maximum_copy_bytes.max(demand.copy_bytes),maximum_release_bytes:SOURCE.maximum_release_bytes.max(demand.release_bytes),maximum_capacity_bytes:SOURCE.maximum_capacity_bytes.max(demand.capacity_bytes),maximum_depth:SOURCE.maximum_depth.max(demand.depth),..SOURCE}}
 /// 🌱️ Births the return table and publisher of the real caller and accounts every byte it allocates.
 pub fn birth_returns(&mut self){let before=self.caller.cumulative_receipt();let(_,heap)=observe(||self.caller.birth_returns(BIRTH));let after=self.caller.cumulative_receipt();assert_eq!(heap,(after.retained_capacity_bytes-before.retained_capacity_bytes,after.released_bytes-before.released_bytes));self.born+=heap.0;self.released+=heap.1;}
 pub fn close(&mut self){for turn in 0..4096{if self.builder.terminal_is_empty(){break}let(answer,heap)=observe(||self.caller.turn(SOURCE,|cx|{close_builder(&mut self.builder,cx)?;Ok(self.builder.terminal_is_empty())}));answer.unwrap();self.record(heap);assert!(turn<4095);}assert!(self.builder.terminal_is_empty());for turn in 0..64{if self.decoder.terminal_is_empty(){break}let(answer,heap)=observe(||self.caller.turn(SOURCE,|cx|{let demand=self.decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;self.decoder.close_on_source(cx)?;Ok(())}));answer.unwrap();self.record(heap);assert!(turn<63);}assert!(self.decoder.terminal_is_empty());self.caller.cancel().cancel_now();for turn in 0..64{if self.caller.terminal_is_empty(){break}let grant=self.retire_grant();let(answer,heap)=observe(||self.caller.retire_step(grant));answer.unwrap();self.record(heap);assert!(turn<63);}assert!(self.caller.terminal_is_empty());let receipt=self.caller.cumulative_receipt();assert_eq!((self.born,self.released),(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(self.born,self.released);}
}
